using HcDeviceCoreTrim;
using Mono.Cecil;
using Mono.Cecil.Cil;
using System.Text.Json;
using System.Security.Cryptography;
using System.Xml.Linq;
using System.Collections;
using System.Resources;
using System.Text.RegularExpressions;

static class CoreTrim {
 static readonly JsonSerializerOptions Json = new(){WriteIndented=true};
 static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
 static IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
 static IEnumerable<TypeDefinition> All(ModuleDefinition m)=>m.Types.SelectMany(All);
 static bool Device(TypeDefinition t)=>t.FullName.StartsWith("HandheldCompanion.Devices.",StringComparison.Ordinal);
 static AssemblyDefinition Read(string p){var r=new DefaultAssemblyResolver();r.AddSearchDirectory(Path.GetDirectoryName(p)!);r.AddSearchDirectory(@"C:\Program Files\dotnet\shared\Microsoft.WindowsDesktop.App\10.0.11");r.AddSearchDirectory(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory());return AssemblyDefinition.ReadAssembly(p,new ReaderParameters{AssemblyResolver=r});}
 static void Write(string p,object o)=>File.WriteAllText(p,JsonSerializer.Serialize(o,Json));
 static void Main(string[] a){switch(a[0]){case "sign":Sign(a[1],a[2],a[3],a[4],a[5]);break;case "tokens":Tokens(a[1],a[2],a[3],a[4]);break;case "inventory":Inventory(a[1],a[2]);break;case "roots":Roots(a[1],a[2],a[3]);break;default:throw new ArgumentException(a[0]);}}
 static object[]? Entries(EmbeddedResource r){if(!r.Name.EndsWith(".resources"))return null;return ResourceBlob.Read(r.GetResourceData()).Entries.Select(e=>(object)new{name=e.Name,type=e.Type,bytes=e.Raw.Length,sha256=Convert.ToHexString(SHA256.HashData(e.Raw)).ToLowerInvariant()}).ToArray();}
 static void Sign(string input,string output,string keyPath,string policyPath,string receipt){using var policy=JsonDocument.Parse(File.ReadAllText(policyPath));string expected=policy.RootElement.GetProperty("PublicKeyHex").GetString()!;using var rsa=RSA.Create();rsa.ImportFromPem(File.ReadAllText(keyPath));var pk=DevelopmentSigning.PublicKey(rsa);if(!Convert.ToHexString(pk).Equals(expected,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Existing development key identity mismatch");using var csp=new RSACryptoServiceProvider();csp.ImportParameters(rsa.ExportParameters(true));using var a=Read(input);string original=a.Name.FullName;var resources=a.MainModule.Resources.OfType<EmbeddedResource>().ToDictionary(r=>r.Name,r=>Convert.ToHexString(SHA256.HashData(r.GetResourceData())).ToLowerInvariant());a.MainModule.Mvid=new Guid(SHA256.HashData(File.ReadAllBytes(input)).AsSpan(0,16));a.Name.PublicKey=pk;a.Write(output,new WriterParameters{StrongNameKeyBlob=csp.ExportCspBlob(true),WriteSymbols=false});var bytes=DevelopmentSigning.Resign(File.ReadAllBytes(output),keyPath,expected);File.WriteAllBytes(output,bytes);if(!DevelopmentSigning.Verify(bytes))throw new InvalidDataException("Independent RSA strong-name verification failed");Write(receipt,new{status="passed",claim="YMCC development derived version only; not an upstream signature",inputSha256=Hash(input),sha256=Hash(output),bytes=bytes.Length,publicKeyToken=DevelopmentSigning.Token(pk),publicKeyHex=Convert.ToHexString(pk).ToLowerInvariant(),oldIdentity=original,newIdentity=a.Name.FullName,mvid=a.MainModule.Mvid,strongNameCryptographicVerification=true,existingKeyReused=true,privateKeyCopied=false,resourcesUnchangedFromLinkedInput=resources});Console.WriteLine($"Signed development derivative: {bytes.Length}B / {Hash(output)}");}
 static void Tokens(string before,string after,string proof,string output){using var p=JsonDocument.Parse(File.ReadAllText(proof));if(p.RootElement.GetProperty("status").GetString()!="passed")throw new InvalidDataException("Independent IL proof did not pass");var result=p.RootElement.GetProperty("results")[0];if(result.GetProperty("beforeSha256").GetString()!=Hash(before)||result.GetProperty("afterSha256").GetString()!=Hash(after))throw new InvalidDataException("Independent IL proof has wrong input hashes");using var a=Read(before);using var b=Read(after);var rows=new List<object>();foreach(var pair in new[]{("GetTouchpads",0x06002847),("GetTouchpadFingers",0x06002848),("InitializeInputOutput",0x0600284f)}){var old=All(a.MainModule).Single(t=>t.FullName=="HandheldCompanion.Controllers.SDLController").Methods.Single(m=>m.Name==pair.Item1);var now=All(b.MainModule).Single(t=>t.FullName==old.DeclaringType.FullName).Methods.Single(m=>m.FullName==old.FullName);if(old.MetadataToken.ToInt32()!=pair.Item2)throw new InvalidDataException("Original fixed fixture token mismatch");rows.Add(new{name=pair.Item1,signature=old.FullName,originalToken=old.MetadataToken.ToInt32(),candidateToken=now.MetadataToken.ToInt32(),allRetainedILEqualityProof=proof});}Write(output,new{status="passed",originalSha256=Hash(before),candidateSha256=Hash(after),independentILProof=proof,independentILProofSha256=Hash(proof),methods=rows});}
 static void Inventory(string p,string o){using var asm=Read(p);var tt=All(asm.MainModule).ToArray();var factory=tt.Single(t=>t.FullName=="HandheldCompanion.Managers.ManagerFactory");Write(o,new{sha256=Hash(p),bytes=new FileInfo(p).Length,identity=asm.Name.FullName,mvid=asm.MainModule.Mvid,types=tt.Select(t=>new{name=t.FullName,baseType=t.BaseType?.FullName,methods=t.Methods.Count,fields=t.Fields.Count}),factoryFields=factory.Fields.Select(f=>new{name=f.Name,type=f.FieldType.FullName}),managerMethods=tt.Where(t=>t.FullName==factory.FullName||factory.Fields.Any(f=>f.FieldType.FullName==t.FullName)||t.FullName=="HandheldCompanion.App").Select(t=>new{name=t.FullName,fields=t.Fields.Select(f=>f.FullName),methods=t.Methods.Select(m=>new{name=m.Name,signature=m.FullName,instructions=m.HasBody?m.Body.Instructions.Select(i=>new{op=i.OpCode.Name,operand=i.Operand?.ToString()}).ToArray():[]})}),resources=asm.MainModule.Resources.Select(r=>new{name=r.Name,kind=r.ResourceType.ToString(),bytes=r is EmbeddedResource e?e.GetResourceData().Length:0,entries=r is EmbeddedResource er?Entries(er):null})});}
 static void Roots(string runtime,string repo,string output){using var hc=Read(Path.Combine(runtime,"HandheldCompanion.dll"));var tt=All(hc.MainModule).ToArray();var provenance=new List<object>();var names=tt.Where(Device).Select(t=>t.FullName).ToHashSet();foreach(var n in names)provenance.Add(new{type=n,reason="Complete Devices namespace including nested types; user preservation requirement",source="baseline metadata"});var refs=new List<object>();foreach(var path in new[]{"FanLab/real-host","FanLab/LightSetter"})foreach(var f in Directory.GetFiles(Path.Combine(repo,path),"*.cs",SearchOption.AllDirectories).Where(f=>!f.Contains("\\obj\\")&&!f.Contains("\\bin\\"))){var lines=File.ReadAllLines(f);for(int i=0;i<lines.Length;i++){if(Regex.IsMatch(lines[i],@"GetType\(|GetTypes\(|GetMethod\(|GetMethods\(|GetMember\(|GetMembers\(|GetField\(|GetProperty\(|GetEvent\(|InvokeStatic\(|FindType\(|InvokeManager|GetStaticMember|SetStaticMember|HandheldCompanion\."))refs.Add(new{path=Path.GetRelativePath(repo,f),line=i+1,text=lines[i]});foreach(Match match in Regex.Matches(lines[i],@"HandheldCompanion\.[A-Za-z0-9_.+`]+")){var n=match.Value.Replace('+','/');if(tt.Any(t=>t.FullName==n)&&n!="HandheldCompanion.App"){names.Add(n);provenance.Add(new{type=n,reason="Named consumer type",source=Path.GetRelativePath(repo,f)+":"+(i+1)});}}}}
 foreach(var n in new[]{"HandheldCompanion.Models.LEDPreset","HandheldCompanion.Misc.GlyphIconInfo","HandheldCompanion.Commands.Functions.Windows.OnScreenKeyboardCommands","HandheldCompanion.ViewModels.DelegateCommand","HandheldCompanion.ViewModels.Commands.RelayCommand","HandheldCompanion.Managers.IManager","HandheldCompanion.Managers.PowerProfileManager"}){names.Add(n);provenance.Add(new{type=n,reason="Actual LightSetter preset model, Host manager reflection, or original seven-constructor fixture",source="FanLab/LightSetter/Program.cs:330-356; FanLab/real-host/Program.cs:3840-3855,4085-4096,5912-5918; tools/hc-devicecore-trim/probes/ModernHeadlessProbe/Program.cs:54-64"});}
 foreach(var parent in names.ToArray())foreach(var t in tt.Where(t=>t.FullName.StartsWith(parent+"/",StringComparison.Ordinal))){names.Add(t.FullName);provenance.Add(new{type=t.FullName,reason="Nested reflection surface of full consumer root",source=parent});}
 var factory=tt.Single(t=>t.FullName=="HandheldCompanion.Managers.ManagerFactory");names.Add(factory.FullName);names.Add("HandheldCompanion.MotherboardInfo");names.Add("HandheldCompanion.Misc.FanProfile");names.Add("HandheldCompanion.Misc.PowerProfile");names.Add("HandheldCompanion.UpdateSource");
 // First experiment intentionally preserves every Factory-field manager type but only consumer-named types' full API. No substitute implementations.
 var elements=names.Order().Select(n=>new XElement("type",new XAttribute("fullname",n),new XAttribute("preserve","all"))).ToList();foreach(var f in factory.Fields){var t=tt.SingleOrDefault(t=>t.FullName==f.FieldType.FullName);if(t!=null&&!names.Contains(t.FullName)){elements.Add(new XElement("type",new XAttribute("fullname",t.FullName),new XAttribute("preserve","nothing")));provenance.Add(new{type=t.FullName,reason="Factory field manager type; closure retains called members",source=f.FullName});}}
 elements.Add(new XElement("type",new XAttribute("fullname","HandheldCompanion.App"),new XAttribute("preserve","fields")));var doc=new XDocument(new XElement("linker",new XElement("assembly",new XAttribute("fullname","HandheldCompanion"),elements)));doc.Save(output);Write(output+".json",new{rootTypes=names.Order(),provenance,consumerReflectionSites=refs,app="all fields; methods only if live closure requires",factory="all members",factoryFieldTypes="type rooted, called methods retained by ILLink",reflectionCompletenessProven=false});Console.WriteLine($"Rooted full API {names.Count}, reflection sites {refs.Count}");}
}






